import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r', 'nxt')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r; self.nxt = None

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return root

def serialize(root):
    q = deque([root])
    out = []
    while q:
        sz = len(q)
        for _ in range(sz):
            n = q.popleft()
            out.append(str(n.v))
            out.append(str(n.l.v) if n.l else 'n')
            out.append(str(n.r.v) if n.r else 'n')
            v = n.nxt
            out.append(str(v.v) if v else 'n')
            if n.l: q.append(n.l)
            if n.r: q.append(n.r)
    return ' '.join(out)

def connect_brute(root):
    if not root: return root
    q = deque([root])
    while q:
        sz = len(q)
        prev = None
        for _ in range(sz):
            n = q.popleft()
            if prev: prev.nxt = n
            prev = n
            if n.l: q.append(n.l)
            if n.r: q.append(n.r)
    return root

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    arr = data[1:1 + n]
    root = build(arr)
    connect_brute(root)
    print(serialize(root))

