def connect_best(root):
    cur = root
    while cur:
        head = None; tail = None
        while cur:
            for child in (cur.l, cur.r):
                if child:
                    if not head: head = child
                    else: tail.nxt = child
                    tail = child
            cur = cur.nxt
        cur = head
    return root

